import type { Metadata } from "next"
import { site } from "@/lib/site"

/** Generated by app/opengraph-image.tsx. Set explicitly: a page-level openGraph object drops the inherited file image. */
const ogImage = { url: "/opengraph-image", width: 1200, height: 630, alt: `${site.name}: natural lawn grass supply and installation` }

type Options = {
  /** Page title without the brand; the layout template appends " | NCR Grass". Keep it under ~50 characters. */
  title: string
  description: string
  path: string
  /** Keep the page out of Google (it is also left out of the sitemap). Links on it are still followed. */
  noindex?: boolean
  /** "article" adds published/modified times to the OpenGraph tags */
  article?: { publishedTime: string; modifiedTime?: string; authors?: string[] }
  /**
   * Set to false on routes that have their own opengraph-image file (blog/[slug], service-areas/[slug]),
   * so the page-specific image is used instead of the shared one.
   */
  sharedImage?: boolean
}

/** Per-page metadata with matching canonical + OpenGraph/Twitter tags. */
export function pageMetadata({ title, description, path, noindex, article, sharedImage = true }: Options): Metadata {
  const fullTitle = `${title} | ${site.name}`
  const images = sharedImage ? [ogImage] : undefined
  return {
    // The root page shares the layout's segment, where the title template doesn't apply
    title: path === "/" ? { absolute: fullTitle } : title,
    description,
    alternates: { canonical: path },
    ...(noindex && { robots: { index: false, follow: true } }),
    openGraph: {
      type: article ? "article" : "website",
      locale: "en_IN",
      siteName: site.name,
      url: path,
      title: fullTitle,
      description,
      ...(article && article),
      ...(images && { images }),
    },
    twitter: { card: "summary_large_image", title: fullTitle, description, ...(images && { images }) },
  }
}
